  final parts = <String>[];
  for (final chunk in preserved.split('\n\n')) {
    final trimmed = chunk.trim();
    if (trimmed.isEmpty) continue;
    parts.add(containsHtmlTags(trimmed)
        ? _convertHtmlToJiraMarkup(trimmed)
