/// Per-paragraph Markdown inline conversion (Java `processTextParagraph`):
/// `1. **bold opener**` → `*bold opener*` bullets, `#`-headings, inline code,
/// bold, and links.
String _processTextParagraph(String text) {
  final output = <String>[];
